import { withPayload } from "@payloadcms/next/withPayload";
import { readFileSync } from "fs";
import { join } from "path";

// Load WordPress → Next.js redirect map (generated by scripts/convert-wp-posts.mjs)
let wpRedirects = [];
try {
  const raw = readFileSync(join(process.cwd(), "scripts", "redirects.json"), "utf-8");
  wpRedirects = JSON.parse(raw);
} catch {
  // Redirects file may not exist yet before first conversion
}

/** @type {import('next').NextConfig} */
const nextConfig = {
  eslint: {
    // Lint is run separately in CI; don't block production builds
    ignoreDuringBuilds: true,
  },

  experimental: {
    // Inline critical CSS and defer non-critical styles to eliminate render-blocking
    optimizeCss: true,
  },

  images: {
    formats: ["image/webp"],
    minimumCacheTTL: 86400,
    remotePatterns: [
      {
        protocol: "https",
        hostname: "i0.wp.com",
        pathname: "/luxewindowworks.com/wp-content/uploads/**",
      },
      {
        protocol: "https",
        hostname: "img.youtube.com",
      },
      {
        // Vercel Blob Storage — for images uploaded via Payload CMS admin
        protocol: "https",
        hostname: "*.public.blob.vercel-storage.com",
      },
    ],
  },

  async headers() {
    return [
      {
        // Static images in /public/images — serve with 1-year immutable cache
        // so CDN edges and browsers don't re-fetch on every visit/PageSpeed run
        source: "/images/:path*",
        headers: [
          {
            key: "Cache-Control",
            value: "public, max-age=31536000, immutable",
          },
        ],
      },
    ];
  },

  async redirects() {
    const staticRedirects = [
      {
        // Consolidated duplicate. Two articles covered moisture-proof window
        // treatments at ~2,900 words each and competed with each other; the
        // kitchens/lake-homes one was the stronger of the pair in Search
        // Console (72 impressions at position 16.5 against 29 at 19.7), so the
        // bathrooms-only article folded into it and redirects here.
        source: '/blog/moisture-proof-window-treatments-for-coeur-dalene-bathrooms',
        destination: '/blog/moisture-proof-window-treatments-kitchens-bathrooms-lake-homes',
        permanent: true,
      },
      {
        source: '/explore-motorized-shades-plantation-shutters-have-a-question-lets-start-the-c',
        destination: '/blog',
        permanent: true,
      },
      {
        source: '/services',
        destination: '/',
        permanent: true,
      },
      {
        source: '/case-studies',
        destination: '/blog',
        permanent: true,
      },
      {
        source: '/why-motorized-shades-fail-in-northern-idaho-and-how-to-fix-them',
        destination: '/blog/why-motorized-shades-fail-in-northern-idaho-and-how-to-fix-them',
        permanent: true,
      },
      {
        source: '/',
        has: [{ type: 'query', key: 'page_id' }],
        destination: '/',
        permanent: true,
      },
      // Shop routes — retired. Norman price increases made the online catalog
      // uncompetitive, so the shop was removed entirely. Redirect old links to
      // the closest matching product page (or homepage) so no bookmark 404s.
      {
        source: '/shop',
        destination: '/',
        permanent: true,
      },
      {
        source: '/shop/cellular-shades',
        destination: '/products/cellular-shades',
        permanent: true,
      },
      {
        source: '/shop/faux-wood-blinds',
        destination: '/products/blinds',
        permanent: true,
      },
      {
        source: '/shop/cart',
        destination: '/',
        permanent: true,
      },
      {
        source: '/shop/success',
        destination: '/',
        permanent: true,
      },
      {
        source: '/shop/cancel',
        destination: '/',
        permanent: true,
      },
    ];

    return [
      ...staticRedirects,
      ...wpRedirects.map((r) => ({
        source: r.source,
        destination: r.destination,
        permanent: true, // 301 redirect — preserves SEO juice
      })),
    ];
  },
};

export default withPayload(nextConfig);
